<template>
  <view class="page-shell"><view class="page-hero"><view class="ink-nav"><text class="nav-back" @click="goBack">‹</text>编辑档期</view></view><view v-if="loading" class="content-layer"><view class="state-card">正在加载档期...</view></view><view v-else-if="!project" class="content-layer"><view class="state-card">未找到档期</view></view><view v-else class="content-layer form-body safe-bottom"><view class="form-card"><text class="section-title">基本信息</text><text class="field-label">课程主题</text><input v-model="form.title" class="field-input"/><text class="field-label">日期</text><input v-model="form.date" class="field-input"/><view class="time-row"><view><text class="field-label">开始时间</text><input v-model="form.start_time" class="field-input"/></view><view><text class="field-label">结束时间</text><input v-model="form.end_time" class="field-input"/></view></view><text class="field-label">地点</text><input v-model="form.location" class="field-input"/><text class="field-label">受众</text><input v-model="form.target_audience" class="field-input"/><text class="field-label">教案大纲（每行一项）</text><textarea v-model="form.outlineText" class="field-textarea"/></view><view class="form-card"><text class="section-title">岗位数量</text><view v-for="item in positionItems" :key="item.key" class="position-row"><text>{{ item.label }}</text><input v-model="form.positions[item.key]" class="number-input" type="number"/><text>人</text></view><text class="form-hint">人数不能低于当前已认领人数。</text></view><button class="save-button" :loading="saving" :disabled="saving" @click="save">保存修改</button><view v-if="canCancel" class="cancel-card"><text class="section-title">取消项目</text><textarea v-model="cancelReason" class="field-textarea" maxlength="200" placeholder="请填写取消原因，成员可在项目详情中查看。"/><view class="cancel-button" @click="cancel">取消该项目</view></view></view></view>
</template>
<script setup lang="ts">import { reactive,ref,computed } from 'vue';import { onLoad } from '@dcloudio/uni-app';import { cancelProject,getProjectDetail,updateProject } from '@/api/project';import { getErrorMessage } from '@/constants/errors';const project=ref<any>(null);const projectId=ref('');const loading=ref(true);const saving=ref(false);const cancelReason=ref('');const form=reactive<any>({title:'',date:'',start_time:'',end_time:'',location:'',target_audience:'',outlineText:'',positions:{assistant:'0',ppt:'0',photographer:'0',logistics:'0'}});const positionItems=[{key:'assistant',label:'助教'},{key:'ppt',label:'PPT'},{key:'photographer',label:'摄影'},{key:'logistics',label:'场务'}];const canCancel=computed(()=>!['completed','cancelled','completion_pending'].includes(project.value?.project_status));const goBack=()=>uni.navigateBack();const load=async()=>{loading.value=true;try{project.value=await getProjectDetail(projectId.value);Object.assign(form,{title:project.value.title,date:project.value.date,start_time:project.value.start_time,end_time:project.value.end_time,location:project.value.location,target_audience:project.value.target_audience,outlineText:(project.value.outline||[]).join('\n')});positionItems.forEach((item)=>form.positions[item.key]=String(project.value.positions?.[item.key]?.total||0))}catch{project.value=null}finally{loading.value=false}};const save=async()=>{if(!form.title.trim()||!form.date||!form.start_time||!form.end_time||!form.location.trim()||!form.target_audience.trim()){uni.showToast({title:'请补全档期信息',icon:'none'});return}saving.value=true;try{project.value=await updateProject(projectId.value,{...form,outline:form.outlineText.split('\n').map((x:string)=>x.trim()).filter(Boolean),positions:Object.fromEntries(positionItems.map((item)=>[item.key,Number(form.positions[item.key]||0)]))});uni.showToast({title:'档期已更新',icon:'success'})}catch(error:any){uni.showToast({title:getErrorMessage(error?.code,error?.message||'保存失败'),icon:'none'})}finally{saving.value=false}};const cancel=()=>{if(!cancelReason.value.trim()){uni.showToast({title:'请填写取消原因',icon:'none'});return}uni.showModal({title:'取消项目',content:'确认取消该项目吗？取消后不可恢复。',confirmText:'确认取消',confirmColor:'#C0392B',success:async(res)=>{if(!res.confirm)return;try{project.value=await cancelProject(projectId.value,cancelReason.value.trim());uni.showToast({title:'项目已取消',icon:'success'})}catch(error:any){uni.showToast({title:getErrorMessage(error?.code,error?.message||'取消失败'),icon:'none'})}}})};onLoad((options:any)=>{projectId.value=options?.id||'';load()});</script>
<style lang="scss" scoped>@import '@/styles/variables.scss';@import '@/styles/mixins.scss';.page-hero{@include ink-header(184rpx);padding:64rpx 34rpx 38rpx;box-sizing:border-box}.nav-back{position:absolute;left:0;font-size:48rpx;line-height:1}.form-body{padding-bottom:140rpx}.form-card,.state-card,.cancel-card{@include soft-card;padding:28rpx;margin-bottom:24rpx}.state-card{color:$text-secondary;text-align:center}.section-title{display:block;color:$text-primary;font-size:29rpx;font-weight:800}.field-label{display:block;margin:22rpx 0 11rpx;color:$text-secondary;font-size:25rpx}.field-input,.field-textarea,.number-input{box-sizing:border-box;border-radius:14rpx;background:rgba(31,78,95,.06);color:$text-primary;font-size:26rpx}.field-input{width:100%;height:80rpx;padding:0 20rpx}.field-textarea{width:100%;min-height:150rpx;padding:18rpx;line-height:1.55}.time-row{display:grid;grid-template-columns:1fr 1fr;gap:16rpx}.position-row{display:flex;align-items:center;gap:16rpx;padding:18rpx 0;border-bottom:1rpx solid rgba(31,78,95,.08);color:$text-primary;font-size:27rpx}.position-row text:first-child{flex:1}.number-input{width:94rpx;height:58rpx;padding:0 10rpx;text-align:center}.form-hint{display:block;margin-top:14rpx;color:$text-muted;font-size:22rpx}.save-button{position:fixed;left:28rpx;right:28rpx;bottom:calc(24rpx + env(safe-area-inset-bottom));height:88rpx;border-radius:22rpx;background:$ink-blue;color:#fff;font-size:30rpx;font-weight:700}.cancel-card{margin-top:10rpx}.cancel-button{width:max-content;margin-top:18rpx;padding:12rpx 20rpx;border-radius:999rpx;background:$red-bg;color:$red;font-size:24rpx;font-weight:700}</style>
